/* Small native runtime for jaot's explicitly checked static Java subset. */
#include "ခေါ်လုပ်.h"
#include "파일규약.h"
typedef unsigned long စက်စကားလုံး;
static စက်စကားလုံး ပုံတင်မှတ်ဉာဏ်သိုလှောင်ရာ[8192];static unsigned သုံးထားပမာဏ;
void 자바실패(void){const char စာသား[]="AOT runtime error\n";ဖိုင်ဒေတာရေး(2,စာသား,sizeof(စာသား)-1);သုံးစွဲသူခေါ်လုပ်(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(စက်စကားလုံး *ထပ်ဆင့်သိုလှောင်ရာ,int *အနက်တန်ဖိုး,စက်စကားလုံး တန်ဖိုး){if(*အနက်တန်ဖိုး<0||*အနက်တန်ဖိုး>=128)자바실패();ထပ်ဆင့်သိုလှောင်ရာ[(*အနက်တန်ဖိုး)++]=တန်ဖိုး;}
စက်စကားလုံး Javaထိပ်ထုတ်တန်ဖိုး(စက်စကားလုံး *ထပ်ဆင့်သိုလှောင်ရာ,int *အနက်တန်ဖိုး){if(*အနက်တန်ဖိုး<=0||*အနက်တန်ဖိုး>128)자바실패();return ထပ်ဆင့်သိုလှောင်ရာ[--*အနက်တန်ဖိုး];}
စက်စကားလုံး 자바배열(int အရေအတွက်){if(အရေအတွက်<0||(unsigned)အရေအတွက်+1>8192-သုံးထားပမာဏ)자바실패();စက်စကားလုံး*ဒေတာနေရာ=ပုံတင်မှတ်ဉာဏ်သိုလှောင်ရာ+သုံးထားပမာဏ;သုံးထားပမာဏ+=အရေအတွက်+1;ဒေတာနေရာ[0]=အရေအတွက်;return (စက်စကားလုံး)ဒေတာနေရာ;}
စက်စကားလုံး *자바색인(စက်စကားလုံး အရာဝတ္ထုကိုးကားချက်,int အရေအတွက်){စက်စကားလုံး*ဒေတာနေရာ=(စက်စကားလုံး*)အရာဝတ္ထုကိုးကားချက်;if(!ဒေတာနေရာ||အရေအတွက်<0||(စက်စကားလုံး)အရေအတွက်>=ဒေတာနေရာ[0])자바실패();return ဒေတာနေရာ+အရေအတွက်+1;}
int 자바길이(စက်စကားလုံး အရာဝတ္ထုကိုးကားချက်){if(!အရာဝတ္ထုကိုးကားချက်)자바실패();return *(စက်စကားလုံး*)အရာဝတ္ထုကိုးကားချက်;}
int 자바나누기(int xတည်နေရာအမှတ်,int yတည်နေရာအမှတ်,int 나머지){if(!yတည်နေရာအမှတ်)자바실패();if(xတည်နေရာအမှတ်==(-2147483647-1)&&yတည်နေရာအမှတ်==-1)return 나머지?0:xတည်နေရာအမှတ်;return 나머지?xတည်နေရာအမှတ်%yတည်နေရာအမှတ်:xတည်နေရာအမှတ်/yတည်နေရာအမှတ်;}
static unsigned အလျား(const char*အက္ခရာစဉ်ဒေတာ){unsigned အရေအတွက်=0;if(!အက္ခရာစဉ်ဒေတာ)자바실패();while(အက္ခရာစဉ်ဒေတာ[အရေအတွက်])အရေအတွက်++;return အရေအတွက်;}
void 자바출력(စက်စကားလုံး ဒေတာနေရာ,int ကိန်းဂဏန်းတန်ဖိုး,int စာကြောင်းသစ်){
    if(ကိန်းဂဏန်းတန်ဖိုး){char ဒုတိယတန်ဖိုး[16];unsigned အရေအတွက်=0;int တန်ဖိုး=(int)ဒေတာနေရာ;unsigned လက္ခဏာမပါတန်ဖိုး=တန်ဖိုး<0?0-(unsigned)တန်ဖိုး:တန်ဖိုး;do{ဒုတိယတန်ဖိုး[အရေအတွက်++]='0'+လက္ခဏာမပါတန်ဖိုး%10;လက္ခဏာမပါတန်ဖိုး/=10;}while(လက္ခဏာမပါတန်ဖိုး);if(တန်ဖိုး<0)ဒုတိယတန်ဖိုး[အရေအတွက်++]='-';while(အရေအတွက်)ဖိုင်ဒေတာရေး(1,ဒုတိယတန်ဖိုး+--အရေအတွက်,1);}
    else{const char*အက္ခရာစဉ်ဒေတာ=ဒေတာနေရာ?(const char*)ဒေတာနေရာ:"null";ဖိုင်ဒေတာရေး(1,အက္ခရာစဉ်ဒေတာ,အလျား(အက္ခရာစဉ်ဒေတာ));}if(စာကြောင်းသစ်)ဖိုင်ဒေတာရေး(1,"\n",1);
}
စက်စကားလုံး 자바파일쓰기(စက်စကားလုံး လမ်း,စက်စကားလုံး တန်ဖိုး){const char*အက္ခရာစဉ်ဒေတာ=(const char*)တန်ဖိုး;unsigned အရေအတွက်=အလျား(အက္ခရာစဉ်ဒေတာ);int ဖိုင်ကိုင်တွယ်ရာ=ဖိုင်ဖွင့်((const char*)လမ်း,သာတန်ဖိုးရေး|없으면만들기|내용비우기,0600);if(ဖိုင်ကိုင်တွယ်ရာ<0)자바실패();int ပြန်ပေးတန်ဖိုး=ဖိုင်ဒေတာရေး(ဖိုင်ကိုင်တွယ်ရာ,အက္ခရာစဉ်ဒေတာ,အရေအတွက်);ဖိုင်ပိတ်(ဖိုင်ကိုင်တွယ်ရာ);if(ပြန်ပေးတန်ဖိုး!=(int)အရေအတွက်)자바실패();return 0;}
စက်စကားလုံး 자바파일읽기(စက်စကားလုံး လမ်း){int ဖိုင်ကိုင်တွယ်ရာ=ဖိုင်ဖွင့်((const char*)လမ်း,သာတန်ဖိုးဖတ်,0);if(ဖိုင်ကိုင်တွယ်ရာ<0)자바실패();int အရေအတွက်=ဖိုင်အရွယ်(ဖိုင်ကိုင်တွယ်ရာ);if(အရေအတွက်<0||အရေအတွက်>16384||(unsigned)(အရေအတွက်+8)/8>8192-သုံးထားပမာဏ)자바실패();char*ဒေတာနေရာ=(char*)(ပုံတင်မှတ်ဉာဏ်သိုလှောင်ရာ+သုံးထားပမာဏ);သုံးထားပမာဏ+=(အရေအတွက်+8)/8;int ပြန်ပေးတန်ဖိုး=ဖိုင်ဒေတာဖတ်(ဖိုင်ကိုင်တွယ်ရာ,ဒေတာနေရာ,အရေအတွက်);ဖိုင်ပိတ်(ဖိုင်ကိုင်တွယ်ရာ);if(ပြန်ပေးတန်ဖိုး!=အရေအတွက်)자바실패();ဒေတာနေရာ[အရေအတွက်]=0;return (စက်စကားလုံး)ဒေတာနေရာ;}
